INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l56',3,12,56,'Our Neighbor, the River','河流,我们的邻居','虚拟语气综合(without/if 引导的非真实条件·与现在相反 if+过去式/主句 could·与过去相反 if+had done/主句 would have done)、must have done(对过去的推测)、现在分词作状语(crowning/holding/giving)、现在分词作定语修饰名词(a raft carrying…)(NCE3 第三册 Unit 3 无 KS 页,考点由课文结构 + Notes on the text 自取;原创承载·河边农场四季庆典与洪水中木筏救邻居,题材温情无害·无需净化;美语化 neighbor/favorite/fall)','形成我们农场东部边界的那条河,一直在我们的生活里扮演着重要角色。没有它,我们就无法谋生——泉水只够供应屋子,别的用水都得从河里抽。这些年来,河几乎成了家里的一员,我们把所有的秘密都告诉它。我们本能地懂得,就像养蜂人懂得他的蜜蜂那样:要是我们把生活中的大事瞒着它,不幸也许就会突然降临。夏天,我们在河边办特别的生日聚会。有时溯流而上,去一处僻静的回水河汊;有时就聚在老船坞里——那是农场的一位前辈盖在草场上、紧挨最深水潭的。我们在水边迎接每一个季节:春天给最小的孩子戴上花冠,夏天在最长的那个夜晚办节庆,秋天为丰收致谢,冬天把一只绿花环抛进水流。久雨之后,河水会漫过堤岸。这在我们这儿是罕见的事,因为只有地势较低的田受影响,那只占农场很小的比例。别的农场没这么走运,洪水有时会给主人带来灾难。有一年严冬,我们眼看着河水漫上低处的草场。牲口早已赶到高地,我们几乎不会有什么损失,却为最近的邻居担心——他们是新来的,地势又低。洪水弄断了电话,我们只能从阁楼的窗口轮流盯着两家田地相接的那一点。就在最紧急的关头,一只木筏出现了,载着他们全家、几只母鸡、狗,还有篮子里的一只猫。他们一定是被上涨的洪水吓过了头,因为他们那座地基牢固的房子,即便几乎被淹,也会稳稳地立着。我们家的男人们拿着长杆蹚进被淹的草场,想钩住木筏的一角,把它拖向我们这边的岸。直到今天,我们仍觉得他们能成功,是个小小的奇迹。','{"q":"Listen and answer — Why had the neighbours left their farm?","options":["Their low-lying farm was flooding","They had sold the farm","They wanted to live in town","Their well had run dry"],"answer_index":0}'::jsonb,'{"title":"虚拟语气(与现在/过去相反) / must have done / 现在分词作状语·定语","intro":"①与现在相反的假设:if + 过去式,主句 would/could/might + 动词原形;without/but for 也可引导:Without it, we could not make a living。②与过去相反的假设:if + had + 过去分词,主句 would/could/might + have + 过去分词:would have stood even if it had been submerged。③must + have + 过去分词,表对过去的肯定推测:They must have become frightened。④现在分词短语作状语(表伴随/方式):crowning the youngest child…;作定语修饰名词(表主动/正在):a raft carrying the family。","table":{"headers":["用法","结构","例子"],"rows":[["与现在相反","if + 过去式, 主句 would/could + 原形","If the river rose, it would flood"],["与过去相反","if + had done, 主句 would have done","would have stood if it had been submerged"],["对过去的推测","must + have + 过去分词","They must have become frightened"],["现在分词作定语","名词 + doing","a raft carrying the family"]]},"specialRules":[{"rule":"without/but for 相当于 if 的否定条件,可引导虚拟句:Without it(=If it were not for it), we could not make a living。","mark":"Without it, we could not …"},{"rule":"与过去相反的推测/假设都用 have + 过去分词:must have become / would have stood。","mark":"must have done / would have done"},{"rule":"美式拼写:neighbor(英式 neighbour)、favorite(英式 favourite)、fall(秋天,英式 autumn)。本课已按美语写。","mark":"neighbor / favorite / fall"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l56',1,NULL,'The river that forms the eastern boundary of our farm has always played an important part in our lives. Without it, we could not make a living, for there is only enough spring water to supply the house, and we must pump from the river for everything else. We tell the river all our secrets, and we know, just as beekeepers know with their bees, that misfortune might overtake us if we kept the great events of our lives from it.','形成我们农场东部边界的那条河,一直在我们的生活里扮演着重要角色。没有它,我们就无法谋生——泉水只够供应屋子,别的用水都得从河里抽。我们把所有的秘密都告诉这条河;我们本能地懂得,就像养蜂人懂得他的蜜蜂那样:要是把生活中的大事瞒着它,不幸也许就会突然降临。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l56',2,NULL,'In summer we hold special river parties. Sometimes we row upstream to a quiet backwater; sometimes we gather at the old boathouse that a predecessor of ours built in the meadow, close by the deepest pool. We welcome each season by the water — crowning the youngest child with flowers in spring, holding a festival on the longest evening of summer, giving thanks for the harvest in fall, and throwing a green wreath into the current in winter.','夏天,我们在河边办特别的生日聚会。有时溯流而上,去一处僻静的回水河汊;有时就聚在老船坞里——那是农场的一位前辈盖在草场上、紧挨最深水潭的。我们在水边迎接每一个季节:春天给最小的孩子戴上花冠,夏天在最长的那个夜晚办节庆,秋天为丰收致谢,冬天把一只绿花环抛进水流。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l56',3,NULL,'After a long spell of rain the river may rise above its banks. This is a rare occurrence here, for only our lower fields, a small proportion of the farm, are ever affected. Other farms are less lucky, and flooding can spell disaster for their owners. One hard winter we watched the water creep up the lower meadows. Our cattle had already been moved to higher ground, so we stood to lose little, but we were worried about our nearest neighbors, newcomers whose land lay low.','久雨之后,河水会漫过堤岸。这在我们这儿是罕见的事,因为只有地势较低的田受影响,那只占农场很小的比例。别的农场没这么走运,洪水有时会给主人带来灾难。有一年严冬,我们眼看着河水漫上低处的草场。牲口早已赶到高地,我们几乎不会有损失,却为最近的邻居担心——他们是新来的,地势又低。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l56',4,NULL,'The flood had put the phone out of order, and from an attic window we took turns watching the point where their land met ours. At the most critical juncture, a raft appeared, carrying the whole family, a few hens, the dog, and a cat in a basket. They must have become unduly frightened by the rising water, for their house, which had sound foundations, would have stood stoutly even if it had been almost submerged.','洪水弄断了电话,我们只能从阁楼的窗口轮流盯着两家田地相接的那一点。就在最紧急的关头,一只木筏出现了,载着他们全家、几只母鸡、狗,还有篮子里的一只猫。他们一定是被上涨的洪水吓过了头,因为他们那座地基牢固的房子,即便几乎被淹,也会稳稳地立着。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l56',5,NULL,'The men of our family waded out with long poles, hoping to grapple a corner of the raft and pull it toward our bank. We still think it a small miracle that they managed to do so.','我们家的男人们拿着长杆蹚进被淹的草场,想钩住木筏的一角,把它拖向我们这边的岸。直到今天,我们仍觉得他们能成功,是个小小的奇迹。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
